import 'dart:async';
import 'dart:convert';
import 'dart:math' as math;
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
import 'live_intelligence.dart';

class Candle { final double o,h,l,c,v; const Candle(this.o,this.h,this.l,this.c,this.v); }
class Factor { final String name, detail; final int score; const Factor(this.name,this.score,this.detail); }
class Analysis { final String trend,structure,candle,psychology,regime,direction,decision,breakout; final int favor,buyer,seller; final double rsi,ema20,ema50,ema200,support,resistance,volumeRatio,atr; final List<Factor> factors; const Analysis({required this.trend,required this.structure,required this.candle,required this.psychology,required this.regime,required this.direction,required this.decision,required this.breakout,required this.favor,required this.buyer,required this.seller,required this.rsi,required this.ema20,required this.ema50,required this.ema200,required this.support,required this.resistance,required this.volumeRatio,required this.atr,required this.factors}); }

class IntegratedApp extends StatelessWidget { const IntegratedApp({super.key}); @override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Master Trading Engine',theme:ThemeData(useMaterial3:true,brightness:Brightness.dark,colorSchemeSeed:Colors.amber),home:const Home()); }
class Home extends StatefulWidget { const Home({super.key}); @override State<Home> createState()=>_HomeState(); }
class _HomeState extends State<Home>{ final symbol=TextEditingController(text:'BTCUSDT'); String tf='5m',error=''; bool loading=false; List<Candle> candles=[]; Analysis? a; Timer? _timer; final engine=const LiveMarketIntelligence();
 @override void initState(){super.initState();_timer=Timer.periodic(const Duration(seconds:30),(_){if(mounted&&!loading)load();});}
 Future<void> load() async { if(loading)return; setState(()=>loading=true); try { final s=symbol.text.trim().toUpperCase(); final uri=Uri.parse('https://api.binance.com/api/v3/klines?symbol=$s&interval=$tf&limit=250'); final r=await http.get(uri).timeout(const Duration(seconds:8)); if(r.statusCode!=200)throw Exception(); final raw=jsonDecode(r.body) as List; final d=raw.map((x)=>Candle(double.parse(x[1]),double.parse(x[2]),double.parse(x[3]),double.parse(x[4]),double.parse(x[5]))).toList(); if(d.length<30)throw Exception(); setState((){candles=d;a=analyze(d);error='';}); } catch(e){ setState(()=>error='No reliable live feed for this symbol. Supported demo feed: Binance symbols such as BTCUSDT.'); } finally { if(mounted)setState(()=>loading=false); } }
 @override void dispose(){_timer?.cancel();symbol.dispose();super.dispose();}
 @override Widget build(BuildContext c){ final x=a; return Scaffold(appBar:AppBar(title:const Text('MASTER TRADING ENGINE'),actions:[const Padding(padding:EdgeInsets.all(8),child:Chip(label:Text('ANALYSIS ONLY')))]),body:ListView(padding:const EdgeInsets.all(10),children:[Card(child:Padding(padding:const EdgeInsets.all(10),child:Row(children:[Expanded(child:TextField(controller:symbol,decoration:const InputDecoration(labelText:'Symbol',border:OutlineInputBorder()))),const SizedBox(width:8),DropdownButton<String>(value:tf,items:const['1m','3m','5m','15m','1h','4h'].map((e)=>DropdownMenuItem<String>(value:e,child:Text(e))).toList(),onChanged:(v){if(v!=null)setState(()=>tf=v);}),IconButton(onPressed:loading?null:load,icon:const Icon(Icons.refresh))]))),if(error.isNotEmpty)Card(child:ListTile(leading:const Icon(Icons.warning),title:const Text('DATA STATUS'),subtitle:Text(error))),if(candles.isNotEmpty)Card(child:Padding(padding:const EdgeInsets.all(8),child:SizedBox(height:240,child:CustomPaint(painter:CandlePainter(candles))))),if(x!=null)...cards(x),if(x==null)const Card(child:Padding(padding:EdgeInsets.all(18),child:Text('Enter a supported symbol and press refresh.')))]); }
 List<Widget> cards(Analysis x)=>[Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(x.decision,style:const TextStyle(fontSize:25,fontWeight:FontWeight.bold)),Text('${x.direction} • Trade Favorability ${x.favor}% • Regime ${x.regime}'),Text('🟢 In favor: ${x.factors.where((f)=>f.score>=70).length}   🟡 Neutral: ${x.factors.where((f)=>f.score>=50&&f.score<70).length}   🔴 Weak: ${x.factors.where((f)=>f.score<50).length}')]))),section('🧠 MARKET PSYCHOLOGY','Buyer ${x.buyer}% • Seller ${x.seller}%\n${x.psychology}'),section('📈 TREND','${x.trend}\nEMA20 ${x.ema20.toStringAsFixed(2)} | EMA50 ${x.ema50.toStringAsFixed(2)} | EMA200 ${x.ema200.toStringAsFixed(2)} | RSI ${x.rsi.toStringAsFixed(1)}'),section('📐 MARKET STRUCTURE',x.structure),section('📍 SUPPORT / RESISTANCE','Support ${x.support.toStringAsFixed(2)}\nResistance ${x.resistance.toStringAsFixed(2)}'),section('🕯️ CANDLESTICK PATTERN',x.candle),section('🚀 BREAKOUT + MOMENTUM','${x.breakout}\nVolume ${x.volumeRatio.toStringAsFixed(2)}x average\nATR ${x.atr.toStringAsFixed(2)}'),section('🔥 STRATEGY CONFLUENCE',x.factors.map((f)=>'${f.score>=70?'🟢':f.score>=50?'🟡':'🔴'} ${f.name}: ${f.score}%\n${f.detail}').join('\n\n')),section('🎯 FINAL SUGGESTION','${x.decision}\nDirection: ${x.direction}\nAnalysis candidate only; not a profit guarantee.')];
 Widget section(String t,String b)=>Card(child:ExpansionTile(title:Text(t,style:const TextStyle(fontWeight:FontWeight.bold)),children:[Padding(padding:const EdgeInsets.fromLTRB(16,0,16,16),child:Align(alignment:Alignment.centerLeft,child:Text(b)))]));
}
Analysis analyze(List<Candle> c){ final input=c.map((x)=>LiveCandle(x.o,x.h,x.l,x.c,x.v)).toList(); final e=const LiveMarketIntelligence(); final i=e.calculate(input); final s=e.analyze(input); final factors=[Factor('Trend Rider',i.bullishTrend||i.bearishTrend?85:45,'EMA 20/50/200 alignment'),Factor('Breakout + Momentum',s.breakoutUp||s.breakoutDown?90:45,s.breakoutUp||s.breakoutDown?'Confirmed level break with volume':'No confirmed breakout'),Factor('Market Structure',s.direction=='NEUTRAL'?50:80,'Recent price direction'),Factor('Support / Resistance',70,'Recent range levels'),Factor('Candlestick',c.last.c>c.last.o?65:55,'Current candle context'),Factor('Volume',i.volumeRatio>=1.25?90:55,'Current vs average volume'),Factor('Psychology',s.direction=='NEUTRAL'?50:80,'Price/volume behavioural inference')]; final fav=(factors.map((f)=>f.score).reduce((a,b)=>a+b)/factors.length).round(); final buyer=(50+(s.direction=='LONG'?20:s.direction=='SHORT'?-20:0)+(i.volumeRatio>1.25?10:0)).clamp(5,95).toInt(); final dec=fav>=70?'🟢 STRONG SETUP':fav>=55?'🟡 WAIT':'🔴 NO TRADE'; final breakout=s.breakoutUp?'Confirmed bullish breakout':s.breakoutDown?'Confirmed bearish breakout':'No confirmed breakout'; return Analysis(trend:i.bullishTrend?'Bullish trend confirmed':i.bearishTrend?'Bearish trend confirmed':'Trend mixed / unclear',structure:c.last.c>c[math.max(0,c.length-10)].c?'Bullish bias':'Bearish bias',candle:c.last.c>c.last.o?'Bullish candle':'Bearish candle',psychology:s.direction=='LONG'?'Buying pressure stronger.':s.direction=='SHORT'?'Selling pressure stronger.':'Buyer and seller evidence mixed.',regime:s.regime,direction:s.direction,decision:dec,breakout:breakout,favor:fav,buyer:buyer,seller:100-buyer,rsi:i.rsi14,ema20:i.ema20,ema50:i.ema50,ema200:i.ema200,support:i.support,resistance:i.resistance,volumeRatio:i.volumeRatio,atr:i.atr14,factors:factors); }
class CandlePainter extends CustomPainter{final List<Candle>d;CandlePainter(this.d);@override void paint(Canvas c,Size s){final a=d.sublist(math.max(0,d.length-80));final hi=a.map((x)=>x.h).reduce(math.max),lo=a.map((x)=>x.l).reduce(math.min),w=s.width/a.length;final p=Paint()..strokeWidth=1;double y(double v)=>s.height-(v-lo)/((hi-lo)==0?1:hi-lo)*s.height;for(var i=0;i<a.length;i++){final x=i*w+w/2,k=a[i];p.color=k.c>=k.o?Colors.greenAccent:Colors.redAccent;c.drawLine(Offset(x,y(k.h)),Offset(x,y(k.l)),p);c.drawRect(Rect.fromLTRB(x-w*.3,y(math.max(k.o,k.c)),x+w*.3,y(math.min(k.o,k.c))),p);}}@override bool shouldRepaint(covariant CandlePainter o)=>o.d!=d;}
